import{_ as r,o as e,c as a,a2 as o}from"./chunks/framework.BWuWLRhz.js";const h=JSON.parse('{"title":"외관","description":"","frontmatter":{},"headers":[],"relativePath":"ko-KR/user-guide/settings/appearance.md","filePath":"ko-KR/user-guide/settings/appearance.md","lastUpdated":1785993908000}'),n={name:"ko-KR/user-guide/settings/appearance.md"};function s(i,t,l,g,p,d){return e(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="외관" tabindex="-1">외관 <a class="header-anchor" href="#외관" aria-label="Permalink to &quot;외관&quot;">​</a></h1><p>사이드바 맨 아래, <a href="./about.html">정보</a> 위에 고정되어 있습니다. <strong>테마 모드</strong>와 테마 선택기 자체, 두 그룹으로 구성됩니다.</p><h2 id="테마-모드" tabindex="-1">테마 모드 <a class="header-anchor" href="#테마-모드" aria-label="Permalink to &quot;테마 모드&quot;">​</a></h2><p>세 개의 카드로, 클릭하면 전환됩니다.</p><ul><li><strong>라이트</strong> — 단일 고정 테마로, 아래 그리드가 라이트 계열 테마만 보이도록 필터링됩니다.</li><li><strong>다크</strong> — 동일하지만 다크 계열 테마로 필터링됩니다.</li><li><strong>시스템 따르기</strong> (라이트/다크가 반씩 나뉜 미리보기) — Lertaro는 단일 고정 테마를 사용하는 대신 여러분이 선택한 두 테마 사이를 전환합니다 — 하나는 Windows가 라이트 모드일 때, 다른 하나는 다크 모드일 때 — 그리고 Windows 자체의 설정을 전환할 때마다 즉시 갱신됩니다(재시작 불필요).</li></ul><p><strong>라이트</strong>와 <strong>다크</strong> 사이를 전환하면 그 계열에서 마지막으로 선택했던 테마로 바로 이동합니다(이는 <strong>시스템 따르기</strong> 자체가 라이트/다크 쌍에 사용하는 것과 동일하게 기억된 선택입니다). 그래서 앞뒤로 전환해도 양쪽 선택이 사라지지 않습니다.</p><h2 id="인터페이스-테마" tabindex="-1">인터페이스 테마 <a class="header-anchor" href="#인터페이스-테마" aria-label="Permalink to &quot;인터페이스 테마&quot;">​</a></h2><p>위에서 <strong>라이트</strong>나 <strong>다크</strong>가 선택되어 있으면, 단일 카드 그리드가 그 계열의 테마만 나열합니다. <strong>시스템 따르기</strong>가 선택되어 있으면, 그리드가 <strong>라이트 테마</strong>와 <strong>다크 테마</strong> 둘로 나뉩니다 — 어떤 테마가 애초에 존재하는지는 전적으로 어떤 테마 플러그인이 설치되어 있는지에 달려 있으므로, 각각은 기본적으로 먼저 설치된 해당 계열의 테마로 설정됩니다.</p><p>각 테마는 이름만이 아니라 카드로 표시됩니다. 검색 상자와 몇 개의 결과 행(하나는 선택된 상태로 표시)을 그 테마 자체의 색상으로 렌더링한 작은 목업이 함께 나타나므로, 실제로 전환하기 전에 테마가 어떻게 보이는지 확인할 수 있습니다. 활성 테마의 카드에는 체크 표시 배지가 나타납니다.</p><p>내장 및 번들 테마 플러그인:</p><ul><li><strong>CoreExtensions</strong> (내장) — Light, Dark, Nord, Sakura, Cyberpunk.</li><li><strong>AnimeThemes</strong> (설치되어 활성화된 경우 번들) — Neon Genesis, Sakura Bloom, Weathering Blue.</li><li><strong>Curated Themes</strong> (설치되어 활성화된 경우 번들) — 열 쌍의 라이트/다크 테마: Glacier, Terracotta, Forest, Amethyst, Crimson, Graphite, Indigo, Mint, Champagne, Amber.</li></ul><p>다른 어떤 테마 플러그인도 같은 방식으로 그리드에 더 많은 카드를 추가할 수 있습니다.</p>',12)])])}const c=r(n,[["render",s]]);export{h as __pageData,c as default};
